<body>

@php
    $grandTotal      = 0;
    $totalPaid       = 0;
    $totalProcessing = 0;

    $paymentStatus = collect($payments)->contains(fn($p) => $p['method'] === 'Card')
        ? 'CONFIRMED'
        : 'PENDING';
    $bulkPaymentMethod = collect($payments)->first()['method'] ?? 'N/A';
    $bulkPaymenttransaction_id= collect($payments)->first()['transaction_id'] ?? 'N/A';

@endphp

<div class="container">

    <!-- HEADER -->
    <table style="margin-bottom:20px;">
        <tr>
            <td>
                <img width="100" src="data:image/png;base64," alt="Base64 Image" />
            </td>
            <td class="text-right">
                <strong style="font-size:18px;">Bulk Invoice</strong><br>
                Date: {{ now()->format('M d, Y') }}
            </td>
        </tr>
    </table>

    <!-- ORDERS TABLE -->
    <table>
        <thead>
            <tr>
                <th>Order No</th>
                <th class="text-center">Items</th>
                <th class="text-right">Order Total ($)</th>
                <th class="text-right">Paid ($)</th>
                <th class="text-right">Balance ($)</th>
            </tr>
        </thead>

        <tbody>
        @foreach ($orders as $order)
            @php
                $orderPayments = collect($payments)->where('order_id', $order->id);
                $paidAmount = $orderPayments->sum('amount');

                $processingFee = $orderPayments
                    ->whereIn('method', ['Card','PayPal'])
                    ->sum(fn($p) => round(($p['amount'] * 3) / 103, 2));
                $withoutfee = $paidAmount - $processingFee;
                $balance = round($order->payment_status['balance_to_be_paid'] - $withoutfee, 2);

                $grandTotal      += $order->payment_status['order_total'];
                $totalPaid       += $paidAmount;
                $totalProcessing += $processingFee;
            @endphp

            <tr>
                <td>{{ $order->order_no }}</td>
                <td class="text-center">{{ $order->orderItems->count() }}</td>
                <td class="text-right">{{ number_format($order->order_total,2) }}</td>
                <td class="text-right paid">{{ number_format($withoutfee,2) }}</td>
                <td class="text-right pending">{{ number_format($balance,2) }}</td>
            </tr>
        @endforeach
        </tbody>
    </table>

    <!-- PAYMENT SUMMARY -->
    <table style="margin-top:25px;">
        <tr>
            <td style="width:55%;"></td>
            <td style="width:45%;">
                <table class="summary-table">
                    <tr>
                        <td>Transaction Id</td>
                        <td class="text-right"><strong>{{ $bulkPaymenttransaction_id }}</strong></td>
                    </tr>
                    <tr>
                        <td>Payment Method</td>
                        <td class="text-right"><strong>{{ $bulkPaymentMethod }}</strong></td>
                    </tr>
                    <tr>
                        <td>Invoice Paid Amount</td>
                        <td class="text-right paid">{{ number_format($totalPaid,2) }}</td>
                    </tr>

                    @if($totalProcessing > 0)
                    <tr>
                        <td>Processing Fee</td>
                        <td class="text-right">{{ number_format($totalProcessing,2) }}</td>
                    </tr>
                    @endif


                    <tr>
                        <td>Payment Status</td>
                        <td class="text-right">
                            @if($paymentStatus === 'CONFIRMED')
                                <span class="paid">CONFIRMED</span>
                            @else
                                <span class="pending">PENDING</span>
                            @endif
                        </td>
                    </tr>
                </table>
            </td>
        </tr>
    </table>

     <table style="margin-top:25px;" class="summary-table">
        <tr>
            <td class="text-center"><h3>Thank you for your business!</h3> <br><small>This is a system generated invoice</small></td>
        </tr>
